/*
 Problem: 3414. Maximum Score of Non-overlapping Intervals
 Language: cpp
 Runtime: 1056 ms (34.59%)
 Memory: 355 MB (30.74%)
 Tags: Array, Binary Search, Dynamic Programming, Sorting
*/
class Solution {
    static constexpr int MAX_SELECTED = 4;

    struct State {
        long long score = 0;
        vector<int> indices;
    };

    static bool isBetter(const State& a, const State& b) {
        if (a.score != b.score) {
            return a.score > b.score;
        }

        return a.indices < b.indices;
    }

    static State addInterval(const State& state, int index, int weight) {
        State result = state;
        result.score += weight;

        auto it = lower_bound(result.indices.begin(), result.indices.end(), index);
        result.indices.insert(it, index);

        return result;
    }

public:
    vector<int> maximumWeight(vector<vector<int>>& intervals) {
        int n = intervals.size();

        vector<array<int, 4>> sortedIntervals;

        for (int i = 0; i < n; ++i) {
            sortedIntervals.push_back({
                intervals[i][0],
                intervals[i][1],
                intervals[i][2],
                i
            });
        }

        sort(sortedIntervals.begin(), sortedIntervals.end());

        vector<int> starts(n);
        for (int i = 0; i < n; ++i) {
            starts[i] = sortedIntervals[i][0];
        }

        // dp[i][k]:
        // Best result using intervals from i onward,
        // with at most k intervals remaining.
        vector<vector<State>> dp(n + 1, vector<State>(MAX_SELECTED + 1));

        for (int i = n - 1; i >= 0; --i) {
            for (int k = 1; k <= MAX_SELECTED; ++k) {

                // Option 1: Skip current interval.
                State skip = dp[i + 1][k];

                // Option 2: Take current interval.
                int right = sortedIntervals[i][1];

                // Next interval must have left > right.
                int next = upper_bound(
                    starts.begin(),
                    starts.end(),
                    right
                ) - starts.begin();

                State take = addInterval(
                    dp[next][k - 1],
                    sortedIntervals[i][3],
                    sortedIntervals[i][2]
                );

                dp[i][k] = isBetter(take, skip) ? take : skip;
            }
        }

        return dp[0][MAX_SELECTED].indices;
    }
};
